/** @format */

/**
 * The 8 addressable sub-shapes of the brain artwork, plus the contour overlay.
 *
 * Artwork: "Brain" by Vector Place on IconScout (see the credit line rendered
 * under the section). The original file is a flat list of paths; the only thing
 * added here is an id, a hemisphere, and a label anchor per shape so the skill
 * tree can be projected onto them.
 *
 * `ALLOCATION_ORDER` is deliberately left-hemisphere-first and contiguous: with
 * two evenly-rated children (Design / Dev) the allocator hands the first child
 * the whole left half and the second the whole right half, which is the reading
 * everyone expects from a brain diagram. Deeper levels then subdivide the same
 * eight slots.
 */

export type Hemisphere = 'left' | 'right';

export interface BrainRegion {
  id: string;
  hemisphere: Hemisphere;
  /**
   * Approximate visual centre in viewBox units. Nothing renders here today —
   * it's kept because eyeballing these back off the path data is tedious, and
   * any in-brain label or marker will want them.
   */
  anchor: { x: number; y: number };
  d: string;
}

export const BRAIN_VIEWBOX = '0 0 49.5 50';

